"""Render independently authored government, learning, and reasoning skill records.

The records contain task-specific operations, branch conditions and examples.
This helper does not read or mutate the shared registry.
"""
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOMAINS = []
RECORDS = []
ARTIFACTS = {}


def domain(code, name, macro, scope, context, risk="low"):
    DOMAINS.append(dict(code=code, name=name, macro=macro, scope=scope,
                        subdomains=["Preparation", "Analysis", "Review"],
                        context=context, risk=risk))


def add(code, raw):
    # slug | title | inputs | five operations | conditional branches | columns |
    # fictional situation | two completed rows | trap | test request
    cells = [x.strip() for x in raw.strip().split("|")]
    assert len(cells) == 10, (code, len(cells), cells[0])
    slug, title, inputs, steps, rules, columns, situation, rows, trap, test = cells
    steps, rules, rows = [x.strip() for x in steps.split("~")], [x.strip() for x in rules.split("~")], [x.strip() for x in rows.split("~")]
    assert len(steps) == 5 and len(rules) == 2 and len(rows) == 2, slug
    for rule in rules:
        assert len(rule.split("=>")) == 3, slug
    assert len(columns.split(";")) == 4
    assert all(len(row.split(";")) == 4 for row in rows), slug
    RECORDS.append(dict(code=code, slug=slug, title=title, inputs=inputs.split(";"), steps=steps,
                        rules=rules, columns=columns.split(";"), situation=situation, rows=rows, trap=trap, test=test))


def render(r, d, number):
    sid = f"{r['code']}-{number:03d}"
    description = f"Prepare {r['title'].lower()} from supplied evidence; use when the request concerns {r['inputs'][0].lower()}."
    triggers = [r['title'].lower(), f"prepare {r['title'].lower()}", f"review my {r['title'].lower()}",
                f"help me with {r['title'].lower()}", f"turn {r['inputs'][0].lower()} into an actionable plan"]
    siblings = [item for item in RECORDS if item['code'] == r['code']]
    neighbors = [siblings[number % len(siblings)], siblings[(number + 1) % len(siblings)]]
    exclusions = [f"{item['title']} [{r['code']}-{siblings.index(item)+1:03d}]" for item in neighbors]
    fm = dict(id=sid, name=r['slug'], domain=d['name'], subdomain="Analysis", version="1.1",
              description=description, triggers=triggers, not_for=exclusions, requires=[], risk_level=d['risk'])
    front = "\n".join(f"{k}: {json.dumps(v, ensure_ascii=False) if isinstance(v, list) else v}" for k,v in fm.items())
    cols = " | ".join(r['columns'])
    input_lines = "\n".join(f"{i}. **{value}** — supply the relevant original material or describe what is unavailable; it determines the scope of the analysis. Default: unknown, never invented." for i,value in enumerate(r['inputs'],1))
    n = len(r['inputs'])
    procedure = "\n".join(f"{i+2}. {step.rstrip('.')} .".replace(" .", ".") for i,step in enumerate(r['steps']))
    branches = "\n".join("- IF " + " THEN ".join(rule.split("=>")[:2]) + " BECAUSE " + rule.split("=>")[2] + "." for rule in r['rules'])
    example_rows = "\n".join(" | ".join(row.split(";")) for row in r['rows'])
    artifact = ARTIFACTS.get(r['slug'])
    artifact_template = '\nArtifact: <the actual draft, prompts, sequence, or other requested deliverable; mark proposals>' if artifact else ''
    artifact_example = '\nArtifact: ' + artifact if artifact else ''
    next_action = r['steps'][-1].rstrip('.')
    open_question = r['rows'][0].split(';')[-1]
    safety = ""
    extra_input = ""
    if d['risk'] == "high":
        extra_input = f"\n{n+2}. **Jurisdiction and personal context** — country, state or locality, responsible authority and current case stage are required; there is no silent jurisdiction default."
        safety = "Before applying a legal, financial, eligibility, or safety interpretation, verify the current rule in the responsible authority's official publication; model knowledge has a cutoff. Use `[VERIFY: the disputed requirement and the responsible official source]` when confirmation is unavailable. Refer a contested right, consequential deadline, or individualized legal conclusion to a licensed professional qualified in the relevant jurisdiction. This workflow prepares information; it does not determine legal entitlement."
    text = f'''---
{front}
---

# {r['title']}

## Purpose
Produce {r['title'].lower()} that another person can use without guessing which evidence supports each action. Keep the request bounded to this task and distinguish an observed fact, a working interpretation, and an unresolved question.

## Inputs to collect
{input_lines}
{n+1}. **Intended use and constraints** — identify the reader, available effort, and decision this output supports. Default: a private working draft using only supplied information.{extra_input}

If a required input is missing and has no safe default, ask in one message with at most 3 questions. Continue only the parts that do not depend on the missing answer; label any provisional work as provisional.

## Procedure
1. Restate the requested outcome in one sentence and identify the smallest useful deliverable; do not expand into adjacent advice merely because the input mentions it.
{procedure}
7. ⚠️ Trace every proposed action back to an input or an explicitly stated condition; when support is missing, replace the conclusion with a verification question instead of filling the gap from memory.
8. Populate the output table with the task-specific findings, retaining disagreements or missing information as visible rows rather than silently dropping them.
9. Check the completed worked logic against an alternative explanation or a changed input; state what would have to change for the recommended next action to change.
10. Run the checklist below and revise any failed item before presenting the deliverable.

{d['context']}

{safety}

## Decision rules
{branches}
- IF source material conflicts THEN preserve both versions and identify the fact needed to resolve the conflict BECAUSE silently choosing a convenient version hides uncertainty.
- IF a requested conclusion depends on unavailable evidence THEN give a conditional next step and name the missing evidence BECAUSE an actionable question is preferable to an unsupported answer.

## Output template
```text
Scope: <one sentence defining this task and its boundaries>
Basis: <up to three supplied inputs; distinguish unknowns>
{cols}
<one row per finding; each cell one concise sentence>
{artifact_template}
Next action: <one concrete action, its owner or role, and the evidence needed>
Unresolved: <up to three verification questions, or None>
```
Use at most 12 rows in the first response. If more are necessary, prioritize blockers and provide the remaining rows as a clearly labeled continuation when requested. Do not bury an unresolved prerequisite in a footnote or represent a draft as an approved result.

## Quality checklist
- [ ] The scope states the actual requested task and excludes unrelated decisions.
- [ ] Every table row is traceable to a supplied input or labeled assumption.
- [ ] The two task-specific conditional branches have been considered.
- [ ] Conflicting evidence remains visible rather than being averaged away.
- [ ] Unknown values remain unknown or have a named verification source.
- [ ] The next action has an identifiable owner or role and observable completion evidence.
- [ ] The example and final output use the same column order and field labels.
- [ ] Any arithmetic has been independently recomputed from the stated inputs.

## Anti-patterns
- **Unsupported certainty**: treating a plausible interpretation as an observed fact. Fix: attach the supporting input or mark the statement provisional.
- **Task-specific shortcut**: {r['trap'].rstrip('.')}. Fix: apply the relevant procedural check before selecting a next action.
- **Missing decision owner**: giving advice that nobody can carry out. Fix: name the role responsible and the artifact that confirms completion.
- **Unbounded expansion**: solving every adjacent problem mentioned in the inputs. Fix: finish the declared scope and list a separate follow-up only when needed.

## Worked example
**Input:**
> Fictional scenario: {r['situation']}

**Output:**
```text
Scope: Prepare {r['title'].lower()} for the fictional case, limited to the supplied facts.
Basis: The fictional scenario above; missing supporting material remains unverified.
{cols}
{example_rows}
{artifact_example}
Next action: The requester or assigned reviewer will complete this task-specific check: {next_action}. Retain the resulting revision or evidence record; do not describe the proposed action as already completed.
Unresolved: Resolve or confirm the first row's verification issue: {open_question}.
```

**Bad output:**
> Everything is ready; proceed without further checks.

This fails because it suppresses the task-specific distinction visible in the table, invents completion, and provides no way to verify the remaining uncertainty.

## Edge cases
- **Only a summary is available**: label findings as based on that summary and request the original excerpt needed for the disputed point.
- **User cannot obtain a missing input**: identify a smaller output that can be completed without it and state the resulting limitation.
- **Two readers need different levels of detail**: preserve a single factual basis and give each reader the subset needed for their decision.
- **The situation changes during the task**: record which input changed, revisit the affected rows, and retain unaffected findings without pretending the entire analysis is new.

## Test case
**Input:**
> Fictional test request: {r['test']}

**Assertions:**
1. The answer uses Scope, Basis, the specified table columns, Next action, and Unresolved in that order.
2. It applies the task-specific operations to the supplied case rather than returning a generic advice list.
3. It identifies the missing or conflicting input before presenting a dependent conclusion as settled.
4. It gives a next action with a responsible role and observable evidence of completion.
'''
    wc = len(re.findall(r"\S+", text.split("---",2)[2]))
    assert 700 <= wc <= 1800, (sid,wc)
    row = dict(id=sid,name=r['slug'],domain_code=r['code'],subdomain="Analysis",description=description,risk_level=d['risk'],requires=[],status="planned")
    return text,row


